import type { Ref } from 'vue'
import { onBeforeUnmount, onMounted, ref, watch } from 'vue'

/**
 * useInView — reactive IntersectionObserver wrapper (generalises the observer
 * behind the `v-reveal` directive in `directives/reveal.ts`).
 *
 * Observers are shared per unique `(rootMargin, threshold)` signature so a page
 * full of demos attaches only a handful of `IntersectionObserver`s rather than
 * one per element. By default it fires once and unobserves on first intersect
 * (the scroll-reveal pattern). When `IntersectionObserver` is unavailable
 * (SSR / very old browsers) the element is treated as in view immediately so
 * content is never blocked.
 */

/** Options accepted by {@link useInView}. */
export interface UseInViewOptions {
  /** Margin around the root, e.g. `'0px 0px -10% 0px'`. */
  rootMargin?: string
  /** Visibility ratio(s) that trigger a callback. */
  threshold?: number | number[]
  /** Reveal once then stop observing (default `true`). */
  once?: boolean
}

/** Per-element callback registry, keyed weakly so detached nodes are collectable. */
const callbacks = new WeakMap<Element, (isInView: boolean) => void>()

/** Shared observers keyed by their serialized option signature. */
const observers = new Map<string, IntersectionObserver>()

function optionsKey(rootMargin: string, threshold: number | number[]): string {
  return `${rootMargin}|${JSON.stringify(threshold)}`
}

function getObserver(rootMargin: string, threshold: number | number[]): IntersectionObserver | null {
  if (typeof window === 'undefined' || typeof IntersectionObserver === 'undefined')
    return null

  const key = optionsKey(rootMargin, threshold)
  let observer = observers.get(key)
  if (!observer) {
    observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          callbacks.get(entry.target)?.(entry.isIntersecting)
        }
      },
      { rootMargin, threshold },
    )
    observers.set(key, observer)
  }
  return observer
}

/**
 * Observe `elRef`'s element and report whether it is in view.
 *
 * @param elRef - template ref to the element to observe.
 * @param options - see {@link UseInViewOptions}.
 * @returns a reactive `isInView` ref.
 */
export function useInView(
  elRef: Ref<HTMLElement | null | undefined>,
  options: UseInViewOptions = {},
): Ref<boolean> {
  const { rootMargin = '0px 0px -10% 0px', threshold = 0.05, once = true } = options
  const isInView = ref(false)

  let observed: Element | null = null
  let observer: IntersectionObserver | null = null

  function unobserve(): void {
    if (observed) {
      observer?.unobserve(observed)
      callbacks.delete(observed)
      observed = null
    }
  }

  function observe(el: HTMLElement): void {
    unobserve()
    observer = getObserver(rootMargin, threshold)
    if (!observer) {
      // No IntersectionObserver → treat as in view immediately.
      isInView.value = true
      return
    }
    callbacks.set(el, (inView) => {
      isInView.value = inView
      if (inView && once)
        unobserve()
    })
    observer.observe(el)
    observed = el
  }

  onMounted(() => {
    if (elRef.value)
      observe(elRef.value)
  })

  watch(elRef, (el) => {
    if (el)
      observe(el)
    else unobserve()
  })

  onBeforeUnmount(unobserve)

  return isInView
}

import type { InjectionKey, Ref } from 'vue'
import { computed, inject, provide, ref } from 'vue'

/**
 * useReducedMotion — central reduced-motion preference for the animations gallery.
 *
 * Resolves to `true` when EITHER the OS exposes
 * `(prefers-reduced-motion: reduce)` OR a page-level override has been turned on
 * via {@link provideMotionPreference}. This lets the gallery honour the user's
 * system setting while also letting `AnimationsPage` force "reduced" live for the
 * demo toggle. SSR-safe (guards `window`/`matchMedia`) and reactive to OS changes.
 */

const REDUCED_MOTION_QUERY = '(prefers-reduced-motion: reduce)'

/** Injection key carrying the page-level reduced-motion override flag. */
const MotionOverrideKey: InjectionKey<Ref<boolean>> = Symbol('dz-motion-override')

/**
 * Module-singleton ref tracking the OS `prefers-reduced-motion` setting. One
 * `matchMedia` listener is attached for the whole app lifetime so every consumer
 * shares a single source of truth.
 */
let osPreference: Ref<boolean> | null = null

function useOsReducedMotion(): Ref<boolean> {
  if (osPreference)
    return osPreference

  const state = ref(false)
  if (typeof window !== 'undefined' && typeof window.matchMedia === 'function') {
    const mql = window.matchMedia(REDUCED_MOTION_QUERY)
    state.value = mql.matches
    mql.addEventListener('change', (event: MediaQueryListEvent) => {
      state.value = event.matches
    })
  }

  osPreference = state
  return state
}

/**
 * provideMotionPreference — install the page-level override that callers of
 * {@link useReducedMotion} downstream will read.
 *
 * Returns the writable override ref so the provider (e.g. `AnimationsPage`) can
 * bind it to a "Reduce motion" toggle. When `true`, every descendant resolves
 * reduced motion regardless of the OS setting.
 *
 * @param initial - initial override value (default `false`).
 */
export function provideMotionPreference(initial = false): Ref<boolean> {
  const override = ref(initial)
  provide(MotionOverrideKey, override)
  return override
}

/**
 * useReducedMotion — reactive boolean, `true` when motion should be reduced.
 *
 * Combines the OS setting with any page-level override installed by
 * {@link provideMotionPreference}. Read-only; mutate the override via the ref
 * returned from `provideMotionPreference`.
 */
export function useReducedMotion(): Readonly<Ref<boolean>> {
  const os = useOsReducedMotion()
  const override = inject(MotionOverrideKey, null)
  return computed(() => os.value || (override?.value ?? false))
}

/**
 * Native-API foundation (docs/animations.md §3.1, §4 — Task N1).
 *
 * A tiny progressive-enhancement layer over the platform motion APIs the gallery
 * now reaches for first: the View Transitions API (SPA), `@starting-style` +
 * `transition-behavior: allow-discrete`, CSS scroll-driven animations, and
 * `interpolate-size: allow-keywords`. Each detector is SSR-safe — it guards
 * `document` / `CSS.supports` so importing this module never touches the DOM at
 * module-evaluation time — and `startViewTransition` always runs the DOM update,
 * so callers get a correct, visible result whether or not the API exists.
 *
 * These helpers UPGRADE existing effects (route/tabs transitions, accordion
 * height, toast entrance); the v1 JS/CSS paths remain the guaranteed floor.
 */

/** The subset of the `ViewTransition` object this layer relies on. */
interface ViewTransitionLike {
  /** Resolves when the update callback's returned promise settles (DOM updated). */
  readonly updateCallbackDone: Promise<void>
}

/**
 * Signature of `document.startViewTransition` (typed locally so this compiles
 *  whether or not the DOM lib ships View Transitions types — Firefox configs).
 */
type StartViewTransitionFn = (callback: () => void | Promise<void>) => ViewTransitionLike

/**
 * Resolve `document.startViewTransition` when present, else `undefined`. Cast
 * through `unknown` so we neither depend on nor collide with the global DOM
 * typings, and bind it so `this` stays `document`. SSR-safe.
 */
function resolveStartViewTransition(): StartViewTransitionFn | undefined {
  if (typeof document === 'undefined')
    return undefined
  const doc = document as unknown as { startViewTransition?: StartViewTransitionFn }
  return typeof doc.startViewTransition === 'function'
    ? (doc.startViewTransition.bind(document) as StartViewTransitionFn)
    : undefined
}

/** Options for {@link startViewTransition}. */
export interface StartViewTransitionOptions {
  /**
   * Force the synchronous fallback (run `update()` with no transition). Pass the
   * resolved reduced-motion preference here so callers never animate against the
   * user's wishes, and so an unsupported browser degrades identically.
   */
  skip?: boolean
}

/**
 * `true` when the same-document View Transitions API is available (Chrome 111+,
 * Safari 18+, Firefox 144+). SSR-safe.
 */
export function supportsViewTransitions(): boolean {
  return resolveStartViewTransition() !== undefined
}

/**
 * `true` when `@starting-style` + `transition-behavior: allow-discrete` are
 * supported (they shipped together — Chrome 117+, Safari 17.5+, Firefox 129+).
 * `transition-behavior` is the reliable `CSS.supports` proxy for the pair. SSR-safe.
 */
export function supportsStartingStyle(): boolean {
  return (
    typeof CSS !== 'undefined'
    && typeof CSS.supports === 'function'
    && CSS.supports('transition-behavior', 'allow-discrete')
  )
}

/**
 * `true` when CSS scroll-driven animations (`animation-timeline: scroll()` /
 * `view()`) are supported (Chrome 115+, Safari 26+; Firefox behind a flag). Not
 * Baseline — always pair with a JS scroll fallback. SSR-safe.
 */
export function supportsScrollTimeline(): boolean {
  return (
    typeof CSS !== 'undefined'
    && typeof CSS.supports === 'function'
    && CSS.supports('animation-timeline', 'scroll()')
  )
}

/**
 * `true` when `interpolate-size: allow-keywords` is supported (Chromium only),
 * enabling true `height: 0 → auto` animation. Never load-bearing — pair with a
 * measured-dimension / `0fr→1fr` fallback. SSR-safe.
 */
export function supportsInterpolateSize(): boolean {
  return (
    typeof CSS !== 'undefined'
    && typeof CSS.supports === 'function'
    && CSS.supports('interpolate-size', 'allow-keywords')
  )
}

/**
 * `true` when the HTML Popover API (`popover` attribute + `popovertarget`,
 * top-layer rendering, native light-dismiss + Esc) is supported — Baseline since
 * 2024 (Chrome 114, Safari 17, Firefox 125). Pair with a `<Transition>` fallback
 * for older engines. SSR-safe (guards `HTMLElement`).
 */
export function supportsPopover(): boolean {
  return (
    typeof HTMLElement !== 'undefined'
    && typeof HTMLElement.prototype === 'object'
    && 'popover' in HTMLElement.prototype
  )
}

/**
 * Run a DOM update inside a View Transition when supported and not skipped,
 * otherwise run it synchronously. The returned promise resolves once the DOM has
 * been updated (NOT when the animation ends), so callers — e.g. a router guard —
 * can sequence work after the swap regardless of which path was taken.
 *
 * ```ts
 * await startViewTransition(() => nextTick(), { skip: reduced.value })
 * ```
 *
 * @param update - mutates the DOM (or returns a promise that does, e.g. `nextTick`).
 * @param opts - `{ skip }` forces the synchronous fallback (reduced motion / unsupported).
 */
export function startViewTransition(
  update: () => void | Promise<void>,
  opts: StartViewTransitionOptions = {},
): Promise<void> {
  const start = opts.skip ? undefined : resolveStartViewTransition()
  if (!start) {
    // Synchronous floor: always run the update so content is never left hidden.
    return Promise.resolve(update())
  }
  return start(update).updateCallbackDone
}
